function of(value) { return { tag: 'Just', value }; }
const nothing = { tag: 'Nothing' };

function chain(maybe, fn) {
  return maybe.tag === 'Just' ? fn(maybe.value) : nothing;
}

function safeDivide(x, y) {
  return y === 0 ? nothing : of(x / y);
}

const result1 = chain(of(20), (x) => safeDivide(x, 4));
const result2 = chain(of(20), (x) => safeDivide(x, 0));

console.log(result1);
console.log(result2);

